-- Wujin platform and merchant backend menus.

SET @wujin_platform_root_id := COALESCE(
  (SELECT `id`
   FROM `system_menu`
   WHERE `deleted` = b'0' AND `path` = '/wujin'
   LIMIT 1),
  7200
);

SET @wujin_platform_menu_id := COALESCE(
  (SELECT `id`
   FROM `system_menu`
   WHERE `deleted` = b'0' AND `component` = 'wujin/platform/index'
   LIMIT 1),
  7201
);

SET @wujin_merchant_menu_id := COALESCE(
  (SELECT `id`
   FROM `system_menu`
   WHERE `deleted` = b'0' AND `path` = '/merchant/wujin'
   LIMIT 1),
  7300
);

SELECT @wujin_platform_root_id, '五金运营后台', '', 1, 57, 0, '/wujin', 'lucide:factory', NULL, NULL, 0, b'1', b'1', b'1', '1', NOW(), '1', NOW(), b'0'
WHERE NOT EXISTS (SELECT 1 FROM `system_menu` WHERE `deleted` = b'0' AND `path` = '/wujin');

SELECT @wujin_platform_menu_id, '平台运营配置', '', 2, 1, @wujin_platform_root_id, 'platform', 'lucide:sliders-horizontal', 'wujin/platform/index', 'WujinPlatformManage', 0, b'1', b'1', b'1', '1', NOW(), '1', NOW(), b'0'
WHERE NOT EXISTS (SELECT 1 FROM `system_menu` WHERE `deleted` = b'0' AND `component` = 'wujin/platform/index');

SELECT @wujin_merchant_menu_id, '五金商家后台', '', 2, 58, 0, '/merchant/wujin', 'lucide:store', 'wujin/merchant/index', 'WujinMerchantManage', 0, b'1', b'1', b'1', '1', NOW(), '1', NOW(), b'0'
WHERE NOT EXISTS (SELECT 1 FROM `system_menu` WHERE `deleted` = b'0' AND `path` = '/merchant/wujin');

SET @wujin_merchant_keep_id := (
  SELECT `id`
  FROM `system_menu`
  WHERE `deleted` = b'0'
    AND `path` = '/merchant/wujin'
    AND `component` = 'wujin/merchant/index'
  ORDER BY `id`
  LIMIT 1
);

UPDATE `system_menu` child
JOIN `system_menu` dup
  ON child.`parent_id` = dup.`id`
SET child.`parent_id` = @wujin_merchant_keep_id,
    child.`updater` = '1',
    child.`update_time` = NOW()
WHERE dup.`deleted` = b'0'
  AND dup.`name` = '五金商家后台'
  AND dup.`component` = 'wujin/merchant/index'
  AND dup.`id` <> @wujin_merchant_keep_id;

UPDATE `system_menu` dup
SET dup.`deleted` = b'1',
    dup.`updater` = '1',
    dup.`update_time` = NOW()
WHERE dup.`deleted` = b'0'
  AND dup.`name` = '五金商家后台'
  AND dup.`component` = 'wujin/merchant/index'
  AND dup.`id` <> @wujin_merchant_keep_id;
















